#' Intervalli di confidenza
#'
#' 
#' @param data .
#' @param data_var Se specificata, l'IC viene calcolato direttamente dai dati
#'   di questa variabile (media se numerica, proporzione del livello di
#'   riferimento se factor binario).
#' @param success_level Per una variabile categoriale, etichetta del livello
#'   considerato "successo" (numeratore della proporzione). Se vuoto, viene
#'   usato il primo livello.
#' @param tuto .
#' @param param Solo per la modalità manuale (senza variabile selezionata).
#' @param n_manual Numerosità del campione in modalità manuale. Il minimo è 2:
#'   con n = 1 la varianza campionaria non è definita (né per la media né per la
#'   proporzione) e il backend rifiuterebbe comunque il calcolo.
#' @param p_manual .
#' @param mean_manual .
#' @param sd_manual .
#' @param N Se fornita, l'IC include il fattore correttivo per popolazioni
#'   finite (1 - f). Mantenere N molto grande (o ignorare) per il caso
#'   "popolazione infinita".
#' @param use_fpc Se TRUE applica (1 - f) all'espressione della varianza dello
#'   stimatore (slide 14, 20, 23). Disattivato per default: la correzione va
#'   abilitata consapevolmente, dichiarando la N effettiva della popolazione.
#'   Con il default attivo uno studente otterrebbe un IC corretto per una
#'   popolazione di 1000 unità senza averlo mai richiesto (e con n = 1000
#'   l'errore standard si annullerebbe).
#' @param confidence .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$instructions} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$inputs} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$result} \tab \tab \tab \tab \tab a table \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$inputs$asDF}
#'
#' \code{as.data.frame(results$inputs)}
#'
#' @export
confint <- function(
    data,
    data_var,
    success_level = "",
    tuto = TRUE,
    param = "proportion",
    n_manual = 100,
    p_manual = 0.5,
    mean_manual = 0,
    sd_manual = 1,
    N = 1000,
    use_fpc = FALSE,
    confidence = 95) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("confint requires jmvcore to be installed (restart may be required)")

    if ( ! missing(data_var)) data_var <- jmvcore::resolveQuo(jmvcore::enquo(data_var))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(data_var), data_var, NULL))


    options <- confintOptions$new(
        data_var = data_var,
        success_level = success_level,
        tuto = tuto,
        param = param,
        n_manual = n_manual,
        p_manual = p_manual,
        mean_manual = mean_manual,
        sd_manual = sd_manual,
        N = N,
        use_fpc = use_fpc,
        confidence = confidence)

    analysis <- confintClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

